fn run(ref mut dev: dyn Device, ref mut game: Game) -> Result[void, GpuError]:
    while game.running:
        started = dev.begin_frame()
        match owns started:
            Some(frame):
                draw_world(ref mut frame, game)
                dev.end_frame(owns frame)          # the GPU was reset (device lost): nothing tells the program
            None:
                pass                               # each later round: None, as for a minimised window
