    fn end_frame(owns frame: Frame):
        this.queue.submit(frame.recording())     # submits, but takes nothing out of `frame`
        this.present(frame.image())
    fn abandon_frame(ref mut frame: Frame):
        this.give_back(frame.image())
        frame.arena().reset()

